Integer compute(Integer n)
    if (n <= 1)
        return 1
    End if
    if (n % 3 == 0)
        return n + compute(n / 3)
    End if
    return compute(n - 1) * 2
End function

Print compute(6)

Integer alt(Integer n)
    if (n <= 1)
        return 1
    End if
    if (n % 2 == 0)
        return n - alt(n - 1)
    else
        return n + alt(n - 1)
    End if
End function

Print alt(5)

Integer condRec(Integer n)
    if (n <= 0)
        return 0
    End if
    if (n % 2 == 0)
        return n + condRec(n / 2)
    else
        return n + condRec(n - 1)
    End if
End function

Print condRec(6)

Integer branchCond(Integer n)
    if (n <= 1)
        return 1
    End if
    if (n > 3)
        return branchCond(n - 1) + branchCond(n - 2)
    End if
    return branchCond(n - 1) + 2
End function

Print branchCond(4)

